// th14_s4_w01  TH14 v1.00b Stage 4 道中第 1 波
// 入口 st04.ecl.txt:946-974（MainSub00 两批各 6 只 ECir00），依赖 ECir00:12-45 / ECir00_at:47-146。

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;

// TH14 原 type4 -> 目标 416（基础半径4，色槽0-15），见 transcribe/th14/bullet-types.md
const TH14_BALL: int = 416;
const BULLET_COLOR: int = 8;
const LASER_COLOR: int = 3;

// ECir00_at:113/130 的 ANIM(type2,a=1) 出生退位移 position -= 4*velocity；
// 动画/减速/无判定阶段按已批准口径省略，退位移保留。
sub shot(a: angle, spd: fx) {
    var x: fx = $self_x - 4fx * spd * cos(a);
    var y: fx = $self_y - 4fx * spd * sin(a);
    _ = fire(TH14_BALL, BULLET_COLOR, x, y, spd, a, none, none);
}

async sub ecir_at() {
    wait(10);                                   // ECir00_at:50
    var rk: int = global(GVAR_RANK);

    // ECir00_at:54-71 激光速度、:72-81 目标长度、:83 diffI($A,1,1,1,8)、
    // :92-111 随机弹颗数与速幅、:133-142 循环间隔
    var lz_sp: fx = 2.7fx;                      // !E
    var lz_len: fx = 128fx;
    var gap: int = 600;
    var iters: int = 1;
    var n_rand: int = 0;                        // !E 由 unless($DIFF >= 1) 跳过随机弹
    var amp: fx = 0fx;
    if rk == RANK_NORMAL { lz_sp = 3.5fx; gap = 50; n_rand = 3; amp = 2.5fx; }
    if rk == RANK_HARD { lz_sp = 4.5fx; lz_len = 144fx; gap = 10; n_rand = 5; amp = 2.5fx; }
    if rk == RANK_LUNATIC { lz_sp = 5.0fx; lz_len = 160fx; gap = 8; iters = 8; n_rand = 5; amp = 3.0fx; }

    var d18: int = 18deg as int;                // ECir00_at:102 第二角 0.31415927f
    var half3: int = (3deg as int) / 2;         // ECir00_at:128 第二角 0.05235988f 的 N=2 半间距
    for it in 0..iters {
        var aim: angle = aim_player();          // ECir00_at:86 etAngle(0, ANGLE_PLAYER, 0)
        // ECir00_at:81/87 laserNew(0,0,L,0,14)+laserOn：Line 恒宽 14 -> 目标判定宽 7
        var lz: int = laser(LASER_COLOR, $self_x, $self_y, aim, 0fx, 7fx, 0, 3000, 0);
        lz_speed(lz, lz_sp, lz_len);
        if rk >= RANK_NORMAL {                  // ECir00_at:88-131
            // 发射器1 第一段 etAim(1,8)：逐弹先角随机(±18°)、后速随机(1+U*amp)
            for i in 0..n_rand {
                var u: fx = ((rand(65536) - 32768) as fx) / 32768;
                var a: angle = aim + (((u * d18) as int) as angle);
                var uv: fx = ((rand(65536) - 32768) as fx) / 65536 + 0.5fx;
                shot(a, 1fx + uv * amp);
            }
            // 发射器1 第二段 etAim(1,1)：N=2 固定扇形，A±1.5°，速度2
            shot(aim + (half3 as angle), 2fx);
            shot(aim - (half3 as angle), 2fx);
        }
        wait(gap);
    }
}

async sub ecir_00(dir: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);                          // ECir00:21 setHurtbox(24,24) -> 受击半径12
    set_hitbox(8fx);                            // ECir00:22 setHitbox(16,16) -> 体碰半径8
    move_to(0, -192fx * dir, 0fx, EASE_LINEAR); // ECir00:32 movePosRel(-192*A, 0)

    // ECir00:33 moveBezierRel(120, 256A,-30, 160A,128, 0,0)：REL Hermite，起点 -192A
    hermite_start(0, -192fx * dir, 160fx * dir, 256fx * dir, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for t1 in 0..120 {
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
        wait(1);
    }
    move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);

    // ECir00:37 moveBezierRel(120, 0,0, -220A,192, -200A,-228)
    hermite_start(0, 160fx * dir, -220fx * dir, 0fx, -200fx * dir, 120);
    hermite_start(1, 128fx, 192fx, 0fx, -228fx, 120);
    spawn ecir_at();                            // ECir00:38 @ECir00_at() async
    for t2 in 0..120 {
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
        wait(1);
    }
    move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    // 源 ECir00:40-43 此后 wait(1000) 循环保活；本段结束点已在 (±220,192) 屏外，主任务自然退场。
}

async sub pattern() {
    wait(OPENING_BUFFER);
    for i1 in 0..3 { _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir_00(1fx)); wait(20); }   // MainSub00:949 B 组
    for i2 in 0..3 { _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir_00(-1fx)); wait(20); }  // :956 C 组，镜像
    wait(180);                                                                           // :960
    for i3 in 0..3 { _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir_00(1fx)); wait(20); }   // :964 D 组
    for i4 in 0..3 { _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir_00(-1fx)); wait(20); }  // :971 E 组，镜像
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
